{"method": "GET", "path": "/", "status": 200, "response": "<!doctype html>\n<html lang=\"zh-CN\">\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>VenueBook · 场地预约与活动报名</title>\n<style>\n  :root { color-scheme: light; }\n  * { box-sizing: border-box; }\n  body { font-family: system-ui, -apple-system, \"Segoe UI\", sans-serif; max-width: 56rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }\n  h1 { margin-bottom: .2rem; }\n  h2 { margin-top: 2.5rem; border-bottom: 1px solid #d9e2ec; padding-bottom: .3rem; }\n  a { color: #175b9c; }\n  .muted { color: #616e7c; }\n  form { background: #f8fafc; border: 1px solid #d9e2ec; border-radius: .6rem; padding: 1.2rem 1.4rem; }\n  .field { margin-bottom: 1rem; }\n  label { display: block; font-weight: 600; margin-bottom: .25rem; }\n  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #b7c2cd; border-radius: .35rem; background: #fff; }\n  input[type=text], input[type=number] { width: 14rem; max-width: 100%; }\n  .hint { font-weight: 400; color: #616e7c; font-size: .9rem; }\n  fieldset { border: 1px dashed #b7c2cd; border-radius: .5rem; margin: 0 0 1rem; padding: .8rem 1rem 1rem; }\n  legend { font-weight: 600; padding: 0 .4rem; }\n  .hour-row { display: flex; flex-wrap: wrap; gap: .5rem; align-items: center; margin-bottom: .5rem; }\n  .hour-row select, .hour-row input { width: auto; }\n  button { font: inherit; padding: .45rem 1.1rem; border-radius: .4rem; border: 1px solid #175b9c; background: #175b9c; color: #fff; cursor: pointer; }\n  button.secondary { background: #fff; color: #175b9c; }\n  button.danger { background: #fff; color: #b42318; border-color: #b42318; padding: .3rem .7rem; }\n  #form-error { margin-top: .9rem; color: #b42318; font-weight: 600; white-space: pre-wrap; display: none; }\n  .venue-card { border: 1px solid #d9e2ec; border-radius: .6rem; padding: 1rem 1.3rem; margin-bottom: 1rem; background: #fff; }\n  .venue-card h3 { margin: 0 0 .3rem; }\n  .venue-meta { color: #52606d; margin: .15rem 0; }\n  .hours { margin: .5rem 0 0; padding: 0; list-style: none; }\n  .hours li { display: inline-block; background: #eef4fa; border-radius: 999px; padding: .15rem .8rem; margin: 0 .4rem .4rem 0; font-size: .92rem; }\n  .empty { color: #616e7c; background: #f8fafc; border: 1px dashed #b7c2cd; border-radius: .6rem; padding: 1.2rem; text-align: center; }\n  .next-day { color: #b42318; font-size: .85em; }\n</style>\n<main>\n  <h1>VenueBook</h1>\n  <p class=\"muted\">场地预约与活动报名。<a href=\"/api/venues\">场地列表接口</a> · <a href=\"/health\">服务状态</a></p>\n\n  <h2>新增场地</h2>\n  <form id=\"venue-form\" novalidate>\n    <div class=\"field\">\n      <label for=\"name\">名称</label>\n      <input id=\"name\" name=\"name\" type=\"text\" autocomplete=\"off\" required>\n    </div>\n    <div class=\"field\">\n      <label for=\"capacity\">容量（人）</label>\n      <input id=\"capacity\" name=\"capacity\" type=\"number\" min=\"1\" step=\"1\" required>\n    </div>\n    <div class=\"field\">\n      <label for=\"timezone\">所在时区</label>\n      <input id=\"timezone\" name=\"timezone\" type=\"text\" list=\"tz-list\" placeholder=\"Asia/Shanghai\" autocomplete=\"off\" required>\n      <datalist id=\"tz-list\">\n        <option value=\"Asia/Shanghai\">\n        <option value=\"Asia/Tokyo\">\n        <option value=\"Asia/Singapore\">\n        <option value=\"Asia/Hong_Kong\">\n        <option value=\"Asia/Taipei\">\n        <option value=\"Asia/Seoul\">\n        <option value=\"Asia/Kolkata\">\n        <option value=\"Asia/Dubai\">\n        <option value=\"Asia/Bangkok\">\n        <option value=\"Europe/London\">\n        <option value=\"Europe/Paris\">\n        <option value=\"Europe/Berlin\">\n        <option value=\"Australia/Sydney\">\n        <option value=\"America/New_York\">\n        <option value=\"America/Chicago\">\n        <option value=\"America/Los_Angeles\">\n        <option value=\"UTC\">\n      </datalist>\n      <div class=\"hint\">有效的 IANA 时区名称，例如 Asia/Shanghai；开放时间按此时区解释。</div>\n    </div>\n    <fieldset>\n      <legend>每周开放时间（可为空）</legend>\n      <div id=\"hours-rows\"></div>\n      <button type=\"button\" id=\"add-hour\" class=\"secondary\">添加开放时段</button>\n    </fieldset>\n    <button type=\"submit\">保存</button>\n    <div id=\"form-error\" role=\"alert\"></div>\n  </form>\n\n  <h2>场地列表</h2>\n  <div id=\"venue-list\">\n    <div class=\"empty\">正在加载…</div>\n  </div>\n</main>\n\n<script>\n(function () {\n  var WEEKDAYS = { 1: \"周一\", 2: \"周二\", 3: \"周三\", 4: \"周四\", 5: \"周五\", 6: \"周六\", 7: \"周日\" };\n\n  var form = document.getElementById(\"venue-form\");\n  var hoursRows = document.getElementById(\"hours-rows\");\n  var errorBox = document.getElementById(\"form-error\");\n  var listBox = document.getElementById(\"venue-list\");\n\n  function showError(message) {\n    errorBox.textContent = message;\n    errorBox.style.display = \"block\";\n  }\n  function clearError() {\n    errorBox.textContent = \"\";\n    errorBox.style.display = \"none\";\n  }\n\n  function addHourRow() {\n    var row = document.createElement(\"div\");\n    row.className = \"hour-row\";\n    var weekday = document.createElement(\"select\");\n    weekday.className = \"hour-weekday\";\n    Object.keys(WEEKDAYS).forEach(function (d) {\n      var opt = document.createElement(\"option\");\n      opt.value = d;\n      opt.textContent = WEEKDAYS[d];\n      weekday.appendChild(opt);\n    });\n    var start = document.createElement(\"input\");\n    start.type = \"time\"; start.className = \"hour-start\"; start.required = true;\n    var dash = document.createElement(\"span\");\n    dash.textContent = \"至\";\n    var end = document.createElement(\"input\");\n    end.type = \"time\"; end.className = \"hour-end\"; end.required = true;\n    var remove = document.createElement(\"button\");\n    remove.type = \"button\";\n    remove.className = \"danger\";\n    remove.textContent = \"删除\";\n    remove.addEventListener(\"click\", function () { row.remove(); });\n    row.appendChild(weekday);\n    row.appendChild(start);\n    row.appendChild(dash);\n    row.appendChild(end);\n    row.appendChild(remove);\n    hoursRows.appendChild(row);\n  }\n  document.getElementById(\"add-hour\").addEventListener(\"click\", addHourRow);\n\n  function collectHours() {\n    var rows = hoursRows.querySelectorAll(\".hour-row\");\n    var hours = [];\n    for (var i = 0; i < rows.length; i++) {\n      var weekday = parseInt(rows[i].querySelector(\".hour-weekday\").value, 10);\n      var start = rows[i].querySelector(\".hour-start\").value;\n      var end = rows[i].querySelector(\".hour-end\").value;\n      if (!start || !end) {\n        return { error: \"第 \" + (i + 1) + \" 个开放时段未填写完整，请补全或删除该时段。\" };\n      }\n      hours.push({ weekday: weekday, start: start, end: end });\n    }\n    return { hours: hours };\n  }\n\n  function toMinutes(hhmm) {\n    var parts = hhmm.split(\":\");\n    return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);\n  }\n\n  function escapeHTML(value) {\n    return String(value).replace(/[&<>\"']/g, function (c) {\n      return { \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c];\n    });\n  }\n\n  // canonicalDigits 按十进制原文校验容量输入：只接受由数字组成的正整数，\n  // 返回去掉前导零后的数字原文；为空、为零或包含负号、小数点等内容时返回\n  // null。全程不经过 Number/parseInt，否则 9007199254740993 这样超过\n  // Number.MAX_SAFE_INTEGER 的值会被悄悄舍入成相邻整数。\n  function canonicalDigits(raw) {\n    if (!/^\\d+$/.test(raw)) return null;\n    var digits = raw.replace(/^0+/, \"\");\n    if (digits === \"\") return null; // 全是 0：容量为零，不接受\n    return digits;\n  }\n\n  // buildVenueRequestBody 直接拼接 JSON 文本，让容量以输入的十进制数字原文\n  // 发送：不能用 JSON.stringify({capacity: 数字})，大整数在转成 Number 时\n  // 已经被舍入，stringify 只会写回错误的值。名称、时区是字符串，交给\n  // JSON.stringify 转义；传输报文中 capacity 仍是 JSON 数字。\n  function buildVenueRequestBody(name, capacityDigits, timezone, hours) {\n    return \"{\" +\n      '\"name\":' + JSON.stringify(name) +\n      ',\"capacity\":' + capacityDigits +\n      ',\"timezone\":' + JSON.stringify(timezone) +\n      ',\"weeklyHours\":' + JSON.stringify(hours) +\n      \"}\";\n  }\n\n  // parseVenuesJSON 解析场地列表，但保留 capacity 数字的十进制原文：\n  // JSON.parse 会把数字存成 float64，超过 2^53 的容量会被舍入成相邻整数。\n  // 这里逐字符扫描 JSON（正确处理字符串内的转义引号），仅当 \"capacity\"\n  // 作为对象键出现时，把其后数字的原文包成字符串，页面拿到的就是服务端\n  // 逐位发出的完整十进制数字（服务端只输出普通整数，不会出现科学计数法）。\n  // 名称等其它字段一律原样复制，绝不改写；线上传输的 JSON 中 capacity\n  // 仍是数字，接口格式不变。\n  function parseVenuesJSON(text) {\n    var out = \"\", i = 0, n = text.length;\n    while (i < n) {\n      if (text[i] !== '\"') {\n        out += text[i];\n        i++;\n        continue;\n      }\n      // 读取完整字符串，跳过转义字符，使名称中出现的 \\\"capacity\\\":1\n      // 之类文本不会被误认为对象键。\n      var tokenStart = i, j = i + 1;\n      while (j < n) {\n        if (text[j] === \"\\\\\") { j += 2; continue; }\n        if (text[j] === '\"') { j++; break; }\n        j++;\n      }\n      var token = text.slice(tokenStart, j);\n      // 对象键后面（允许空白）必然是 ':'；字符串值后面只能是 ',' 或 '}'。\n      var k = j;\n      while (k < n && /\\s/.test(text[k])) k++;\n      if (text[k] !== \":\" || JSON.parse(token) !== \"capacity\") {\n        out += token;\n        i = j;\n        continue;\n      }\n      // 复制到 ':' 之后（含中间空白），再把数字原文引用为字符串。\n      out += token + text.slice(j, k + 1);\n      var p = k + 1;\n      while (p < n && /\\s/.test(text[p])) { out += text[p]; p++; }\n      var numStart = p;\n      while (p < n && /[-+0-9eE.]/.test(text[p])) p++;\n      out += JSON.stringify(text.slice(numStart, p));\n      i = p;\n    }\n    return JSON.parse(out);\n  }\n\n  function renderVenues(venues) {\n    if (!venues.length) {\n      listBox.innerHTML = '<div class=\"empty\">还没有场地记录。</div>';\n      return;\n    }\n    var sortedHours = function (hours) {\n      return hours.slice().sort(function (a, b) {\n        if (a.weekday !== b.weekday) return a.weekday - b.weekday;\n        return toMinutes(a.start) - toMinutes(b.start);\n      });\n    };\n    listBox.innerHTML = venues.map(function (venue) {\n      var hoursHTML;\n      if (!venue.weeklyHours || !venue.weeklyHours.length) {\n        hoursHTML = '<p class=\"venue-meta\">开放时段：暂未开放</p>';\n      } else {\n        var items = sortedHours(venue.weeklyHours).map(function (h) {\n          var overnight = toMinutes(h.end) < toMinutes(h.start);\n          var endLabel = overnight ? '<span class=\"next-day\">次日 ' + escapeHTML(h.end) + \"</span>\" : escapeHTML(h.end);\n          return \"<li>\" + WEEKDAYS[h.weekday] + \" \" + escapeHTML(h.start) + \" – \" + endLabel + \"</li>\";\n        }).join(\"\");\n        hoursHTML = '<ul class=\"hours\">' + items + \"</ul>\";\n      }\n      return '<article class=\"venue-card\">' +\n        \"<h3>\" + escapeHTML(venue.name) + \"</h3>\" +\n        '<p class=\"venue-meta\">容量：' + escapeHTML(venue.capacity) + \" 人</p>\" +\n        '<p class=\"venue-meta\">时区：' + escapeHTML(venue.timezone) + \"</p>\" +\n        hoursHTML +\n        \"</article>\";\n    }).join(\"\");\n  }\n\n  function loadVenues() {\n    return fetch(\"/api/venues\", { headers: { Accept: \"application/json\" } })\n      .then(function (res) {\n        if (!res.ok) throw new Error(\"读取场地列表失败（HTTP \" + res.status + \"）\");\n        return res.text();\n      })\n      .then(function (text) {\n        var data;\n        try {\n          data = parseVenuesJSON(text);\n        } catch (e) {\n          throw new Error(\"读取场地列表失败：响应不是有效的 JSON\");\n        }\n        renderVenues(data.venues || []);\n      })\n      .catch(function (err) {\n        listBox.innerHTML = '<div class=\"empty\">' + escapeHTML(err.message) + \"</div>\";\n      });\n  }\n\n  form.addEventListener(\"submit\", function (event) {\n    event.preventDefault();\n    clearError();\n\n    var name = document.getElementById(\"name\").value.trim();\n    var capacityDigits = canonicalDigits(document.getElementById(\"capacity\").value);\n    var timezone = document.getElementById(\"timezone\").value.trim();\n\n    if (!name) { showError(\"保存失败：名称不能为空。\"); return; }\n    if (capacityDigits === null) { showError(\"保存失败：容量必须是正整数。\"); return; }\n    if (!timezone) { showError(\"保存失败：请填写所在时区。\"); return; }\n\n    var collected = collectHours();\n    if (collected.error) { showError(\"保存失败：\" + collected.error); return; }\n\n    // 失败时不重置表单，保留全部填写内容。\n    fetch(\"/api/venues\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\", Accept: \"application/json\" },\n      // 容量按输入的十进制原文作为 JSON 数字发送，不经过 Number/parseInt：\n      // 是否超出服务端范围由服务端按这个准确整数判断，绝不先舍入再提交。\n      body: buildVenueRequestBody(name, capacityDigits, timezone, collected.hours)\n    }).then(function (res) {\n      return res.json().catch(function () { return {}; }).then(function (body) {\n        return { ok: res.ok, status: res.status, body: body };\n      });\n    }).then(function (result) {\n      if (!result.ok) {\n        var reason = result.body && result.body.error ? result.body.error : \"HTTP \" + result.status;\n        showError(\"保存失败：\" + reason);\n        return;\n      }\n      form.reset();\n      hoursRows.innerHTML = \"\";\n      clearError();\n      return loadVenues();\n    }).catch(function (err) {\n      showError(\"保存失败：无法连接服务（\" + err.message + \"），请稍后重试。\");\n    });\n  });\n\n  loadVenues();\n})();\n</script>\n</html>\n"}
